/* Self-contained synthetic teaching example for 1D isothermal GLOBAL OC breakthrough fitting.
 * Every observation is generated by the very same governing forward model at a
 * known true k and is explicitly marked as SYNTHETIC; it is not laboratory data.
 * Do not silently reuse this calibrated example for physical parameter estimates.
 */
import {simulateGlobalOc1D} from "../column/global_oc1d.js";
const $=id=>document.getElementById(id);
const put=(id,v)=>{const el=$(id);if(!el)throw Error("Missing setting "+id);el.value=String(v);};
const setting={
 length:.24,radius:.02,porosity:.4,density:850,velocity:.02,
 dzDisp:2.2e-5,drDisp:0,feed:.8,initialC:0,qMax:.006,affinity:.7,
 initialQ:0,nz:24,nr:1,endTime:80,beStepsPerOutput:8,
 inletAmp:0,velocityAmp:0
};
function demoConfig(){
 return {
  geometry:{length:setting.length,radius:setting.radius},
  bed:{porosity:setting.porosity,particleDensity:setting.density},
  flow:{superficialVelocity:setting.velocity,axialDispersion:setting.dzDisp,
   radialDispersion:0,inletAmplitude:0,velocityAmplitude:0},
  gas:{direction:"adsorption",feedConcentration:setting.feed,initialConcentration:0,
   temperatureK:298.15,totalPressurePa:101325},
  adsorption:{initialLoading:0,rateConstant:.22,equilibrium:{type:"langmuir",qMax:setting.qMax,affinity:setting.affinity}},
  grid:{nz:24,nr:1},
  simulation:{endTime:80,snapshots:4,cfl:.75,maxSteps:120000,beStepsPerOutput:8}
 };
}
const status=(message,isError=false)=>{const el=$("btDemoStatus");el.textContent=message;el.className="status"+(isError?" error":"");};
async function loadAndFit(){
 const button=$("btDemo");
 button.disabled=true;
 try{
  status("Generating synthetic breakthrough observations with 1D Global OC...");
  const simulated=await simulateGlobalOc1D(demoConfig(),{
   yieldTask:()=>new Promise(resolve=>setTimeout(resolve,0))
  });
  for(const [id,value] of Object.entries(setting))put(id,value);
  put("rate",.06); // deliberately biased starting guess
  put("fitBudget",85);
  put("fitMode","k");put("fitSolver","globaloc1d");
  put("direction","adsorption");put("solverMode","globaloc1d");put("thermalMode","isothermal");
  put("equilibriumMode","langmuir");put("kineticMode","manual");
  for(const id of ["equilibriumMode","kineticMode","thermalMode"])
    $(id).dispatchEvent(new Event("change"));
  // Applying one standard change ensures the main Column controller refreshes
  // all dependent mode panels while leaving the input values intact.
  $("solverMode").dispatchEvent(new Event("change"));
  $("expApplySettings").click();
  // The current solver-mode change handler recalls a saved 1D grid size. Override
  // it after the mode change to preserve the exact data-generation discretization.
  put("nz",24);put("nr",1);put("rate",.06);
  const csv="time_s,ratio\n"+simulated.samples.filter((_,i)=>i%2===0)
   .map(s=>s.time.toFixed(8)+","+s.outletFraction.toFixed(10)).join("\n");
  $("experimentData").value=csv;
  $("experimentData").dispatchEvent(new Event("input",{bubbles:true}));
  $("expAnalyze").click();
  if(!$("experimentStatus").textContent.includes("analyzed"))
   throw Error("The example data could not be analyzed: "+$("experimentStatus").textContent);
  status("Synthetic observations loaded. Starting GLOBAL OC estimation of kLDF (true 0.22 s⁻¹)...");
  $("fitBtn").click();
  if($("fitStatus").textContent.toLowerCase().includes("failed"))
   throw Error($("fitStatus").textContent);
  status("Synthetic 1D Global OC fitting started. The lower Results section will show estimated kLDF, RMSE and the fitted breakthrough curve.");
  document.querySelector(".breakthrough-results")?.scrollIntoView({behavior:"smooth",block:"start"});
 }catch(error){status("Could not load example: "+(error.message||error),true);}
 finally{button.disabled=false;}
}
document.addEventListener('breakthrough:fit-completed',event=>{
  if(!$("btDemoStatus").textContent.includes("Synthetic"))return;
  const result=event.detail?.fit;
  if(!result)return;
  const value=result.fitted?.k;
  status("Synthetic breakthrough fit completed: recovered kLDF = "+
    (Number.isFinite(value)?value.toPrecision(5):"not estimated")+
    " s⁻¹ (known truth 0.22 s⁻¹), RMSE = "+result.metrics.rmse.toPrecision(4)+
    ". See the measured-versus-fitted chart below.");
});
$("btImportIsotherm")?.addEventListener("click",()=>$("isothermFile").click());
$("btImportKinetic")?.addEventListener("click",()=>$("kineticFile").click());
$("btDemo")?.addEventListener("click",()=>void loadAndFit());
